import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"UEFI 固件架构与技术综述","description":"","frontmatter":{},"headers":[],"relativePath":"notes/hardware/firmware-boot/uefi.md","filePath":"notes/hardware/firmware-boot/uefi.md"}'),i={name:"notes/hardware/firmware-boot/uefi.md"};function n(l,e,s,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="uefi-固件架构与技术综述" tabindex="-1">UEFI 固件架构与技术综述 <a class="header-anchor" href="#uefi-固件架构与技术综述" aria-label="Permalink to &quot;UEFI 固件架构与技术综述&quot;">​</a></h1><h2 id="_1-uefi-概述" tabindex="-1">1. UEFI 概述 <a class="header-anchor" href="#_1-uefi-概述" aria-label="Permalink to &quot;1. UEFI 概述&quot;">​</a></h2><p>UEFI（Unified Extensible Firmware Interface）是现代计算机系统固件的标准架构，取代了传统 BIOS。它定义了从硬件复位到操作系统接管之间，固件所必须提供的接口规范与执行框架。UEFI 核心作用包括：</p><ul><li><strong>硬件初始化</strong>：完成 CPU、内存、总线及外设的早期初始化，构建操作系统可依赖的运行时环境。</li><li><strong>设备驱动模型</strong>：通过 Handle / Protocol 抽象和 Driver Binding 机制，实现硬件驱动的模块化加载与动态连接。</li><li><strong>启动管理</strong>：基于 NVRAM 中的启动变量（BootOrder / Boot####），按策略选择并加载操作系统引导程序。</li><li><strong>安全体系</strong>：提供 Secure Boot 镜像认证机制，确保固件及 OS Loader 的完整性与可信度。</li><li><strong>运行时服务</strong>：操作系统接管后，仍提供变量读写、时钟、重置等 Runtime Services。</li></ul><p>UEFI 规范由 UEFI Forum 维护，平台初始化（Platform Initialization, PI）架构定义了固件内部各阶段的标准化接口。</p><hr><h2 id="_2-uefi-启动阶段总览" tabindex="-1">2. UEFI 启动阶段总览 <a class="header-anchor" href="#_2-uefi-启动阶段总览" aria-label="Permalink to &quot;2. UEFI 启动阶段总览&quot;">​</a></h2><p>UEFI 固件启动流程按执行顺序划分为六个阶段，各阶段职责明确、服务递进：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU Reset → SEC → PEI → DXE → BDS → TSL → RT → OS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>阶段</th><th>全称</th><th>核心职责</th></tr></thead><tbody><tr><td>SEC</td><td>Security</td><td>安全验证、临时 RAM、PEI Foundation 引导</td></tr><tr><td>PEI</td><td>Pre-EFI Initialization</td><td>早期初始化（DRAM / CPU）、HOB 列表构建</td></tr><tr><td>DXE</td><td>Driver Execution Environment</td><td>驱动执行、总线枚举、Boot Services 构建</td></tr><tr><td>BDS</td><td>Boot Device Selection</td><td>控制台初始化、设备连接、启动策略执行</td></tr><tr><td>TSL</td><td>OS Load</td><td>OS Loader 运行、ExitBootServices</td></tr><tr><td>RT</td><td>Runtime</td><td>操作系统接管后，Runtime Services 持续服务</td></tr></tbody></table><hr><h2 id="_3-各阶段详细说明" tabindex="-1">3. 各阶段详细说明 <a class="header-anchor" href="#_3-各阶段详细说明" aria-label="Permalink to &quot;3. 各阶段详细说明&quot;">​</a></h2><h3 id="_3-1-sec-阶段-security-phase" tabindex="-1">3.1 SEC 阶段（Security Phase） <a class="header-anchor" href="#_3-1-sec-阶段-security-phase" aria-label="Permalink to &quot;3.1 SEC 阶段（Security Phase）&quot;">​</a></h3><p>SEC 是 CPU 复位后的首个执行阶段，负责建立最基础的执行环境。</p><p><strong>核心职责</strong>：</p><ul><li>处理所有平台重启事件（冷启动、暖启动、Sx 状态恢复等）。</li><li>创建临时内存存储（Cache-as-RAM），在 DRAM 不可用时提供代码和数据存放空间。</li><li>作为系统信任根（Root of Trust），验证固件完整性。</li><li>建立 CPU 基本执行模式，切换到 32 位兼容模式或 64 长模式。</li><li>通过 <code>EFI_SEC_PEI_HAND_OFF</code> 结构将控制权和 Hand-Off 信息传递给 PEI Foundation。</li></ul><p>SEC 阶段通常以汇编语言编写，环境极为受限，不具备 C 语言运行时支持。</p><h3 id="_3-2-pei-阶段-pre-efi-initialization-phase" tabindex="-1">3.2 PEI 阶段（Pre-EFI Initialization Phase） <a class="header-anchor" href="#_3-2-pei-阶段-pre-efi-initialization-phase" aria-label="Permalink to &quot;3.2 PEI 阶段（Pre-EFI Initialization Phase）&quot;">​</a></h3><p>PEI 阶段在临时内存或永久内存中运行，完成从最小化环境到完整内存环境的过渡。</p><p><strong>核心职责</strong>：</p><ul><li>初始化北桥、内存控制器（MRC），完成 DRAM 发现与训练，安装永久内存。</li><li>初始化 CPU 基本功能（APIC、缓存策略、微码加载）。</li><li>通过 PEI Foundation 调度 PEIM（Pre-EFI Initialization Module），利用 PPI（PEIM-to-PEIM Interface）实现模块间通信。</li><li>构建 HOB（Hand-Off Block）列表，记录 PEI 阶段的初始化结果和资源信息。</li></ul><p><strong>关键机制</strong>：</p><ul><li><strong>PEI Dispatcher</strong>：根据 PEIM 的依赖表达式（Depex）进行拓扑排序调度，确保模块按依赖关系正确执行。</li><li><strong>HOB 列表</strong>：PEI 与 DXE 之间的数据传递机制。包括 PHIT HOB（必须是第一个）、资源描述 HOB、内存分配 HOB、固件卷 HOB、CPU HOB 等类型。</li><li><strong>临时内存切换</strong>：PEI 前期在临时 RAM 运行，DRAM 就绪后调用 <code>InstallPeiMemory()</code> 切换到永久内存，临时 RAM 被清除。</li></ul><p>PEI 阶段不依赖 UEFI 服务协议，使用 PEI Services 表（PPI Services、HOB Services、Firmware Volume Services 等）。</p><h3 id="_3-3-dxe-阶段-driver-execution-environment-phase" tabindex="-1">3.3 DXE 阶段（Driver Execution Environment Phase） <a class="header-anchor" href="#_3-3-dxe-阶段-driver-execution-environment-phase" aria-label="Permalink to &quot;3.3 DXE 阶段（Driver Execution Environment Phase）&quot;">​</a></h3><p>DXE 是 UEFI 固件最核心的阶段，建立了完整的 UEFI 运行环境。</p><p><strong>核心职责</strong>：</p><ul><li>DXE Foundation 解析 PEI 传递的 HOB 列表，构建 EFI 系统表（gST）、Boot Services（gBS）、Runtime Services（gRT）及 DXE Services 表。</li><li>DXE Dispatcher 从固件卷（FV）中扫描、解析 DXE 驱动，根据 Depex 依赖表达式执行拓扑排序调度。</li><li>枚举 PCIe 总线、发现所有总线设备，分配 Bus Number 和 BAR 资源。</li><li>加载各类设备驱动（NVMe、USB、SATA、Network 等），初始化外设子系统。</li><li>生成 ACPI 表和 SMBIOS 表，为操作系统提供硬件描述信息。</li><li>当 Dispatcher 无更多驱动可调度时，通过 <code>EFI_BDS_ARCH_PROTOCOL</code> 将控制权移交 BDS。</li></ul><p><strong>驱动调度机制</strong>：</p><ul><li><strong>Apriori 文件</strong>：指定必须最先执行的关键驱动（如芯片组驱动），赋予最高调度优先级。</li><li><strong>Depex 依赖表达式</strong>：驱动内置的 Protocol 依赖声明，使用 AND / OR / NOT 等逻辑运算符组合 Protocol GUID。只有前置依赖满足时，驱动方可执行。</li><li><strong>Protocol Database</strong>：全局协议注册表，驱动安装的新 Protocol 触发对候选池的新一轮依赖检查。</li><li><strong>调度流程</strong>：扫描 FV → 解析 Depex → 处理 Apriori → 执行已就绪队列 → 重评估候选池 → 循环直至无新驱动可调度。</li></ul><h3 id="_3-4-bds-阶段-boot-device-selection-phase" tabindex="-1">3.4 BDS 阶段（Boot Device Selection Phase） <a class="header-anchor" href="#_3-4-bds-阶段-boot-device-selection-phase" aria-label="Permalink to &quot;3.4 BDS 阶段（Boot Device Selection Phase）&quot;">​</a></h3><p>BDS 阶段基于 DXE 准备好的服务和驱动，完成启动设备选择并加载操作系统引导程序。</p><p><strong>核心职责</strong>：</p><ul><li><strong>控制台初始化</strong>：连接 ConIn（键盘）、ConOut（屏幕）、StdErr 设备驱动，更新系统表中的控制台指针。通过 GOP（Graphics Output Protocol）渲染 OEM 启动 Logo。</li><li><strong>设备连接</strong>：对未连接的 Controller / Device Handle 执行 <code>ConnectController()</code>，递归匹配 Driver Binding 的 Supported / Start 流程，加载 Option ROM。</li><li><strong>启动策略执行</strong>：通过 <code>PlatformBootManagerLib</code> 读取 NVRAM 中启动变量，按 BootOrder 排序选择启动项。</li><li><strong>OS Loader 加载</strong>：通过 Device Path 定位 EFI 文件，调用 <code>LoadImage()</code> 加载到内存，再调用 <code>StartImage()</code> 执行。</li><li><strong>系统资产信息收集</strong>：在服务器平台上，收集 BIOS / CPU / DIMM / PCIe 信息并推送给 BMC。</li></ul><p><strong>启动变量体系</strong>：</p><table tabindex="0"><thead><tr><th>变量</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>BootOrder</td><td>持久</td><td>启动优先级数组，每次启动按序尝试</td></tr><tr><td>Boot####</td><td>持久</td><td>单个启动项，含 EFI_LOAD_OPTION 结构（Attributes、Description、Device Path、OptionalData）</td></tr><tr><td>BootNext</td><td>一次性</td><td>优先于 BootOrder，仅对本次启动有效，处理后自动清除</td></tr><tr><td>BootCurrent</td><td>只读</td><td>记录本次实际使用的启动项编号，由固件写入</td></tr></tbody></table><p><strong>设备连接链路（以 NVMe 为例）</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PCI 枚举发现 NVMe Controller</span></span>
<span class="line"><span>  → PciIo Protocol（PCI 层访问）</span></span>
<span class="line"><span>  → NvmExpressDxe.Start() → BlockIo Protocol（块读写）</span></span>
<span class="line"><span>  → PartitionDxe.Start() → BlockIo + DevicePath（分区级）</span></span>
<span class="line"><span>  → FatDxe.Start() → SimpleFileSystem（文件系统）</span></span>
<span class="line"><span>  → bootmgfw.efi 可打开</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>DXE 到 BDS 的移交</strong>：BDS 以 DXE Driver 形式安装 <code>EFI_BDS_ARCH_PROTOCOL</code>，DXE Core 通过此协议找到 BDS 并调用 <code>BdsEntry()</code>。BDS 接管后不应返回，否则 DXE Core 进入死循环。</p><h3 id="_3-5-tsl-阶段-os-loader-phase" tabindex="-1">3.5 TSL 阶段（OS Loader Phase） <a class="header-anchor" href="#_3-5-tsl-阶段-os-loader-phase" aria-label="Permalink to &quot;3.5 TSL 阶段（OS Loader Phase）&quot;">​</a></h3><p>OS Loader（如 Windows 的 <code>bootmgfw.efi</code>、Linux 的 <code>grubx64.efi</code>）由 BDS 加载并执行，负责准备操作系统运行环境。</p><p><strong>核心职责</strong>：</p><ul><li>调用 <code>GetMemoryMap()</code> 获取当前内存布局快照及 MapKey。</li><li>加载操作系统内核及必需的驱动程序。</li><li>调用 <code>ExitBootServices(MapKey)</code> 完成固件与操作系统的最终交接。</li></ul><p><strong>ExitBootServices 的影响</strong>：</p><ul><li>Boot Services 不可用（包括 LoadImage、ConnectController 等）。</li><li>Runtime Services 仍可用（GetVariable / SetVariable、时钟、ResetSystem、SetVirtualAddressMap）。</li><li>触发 <code>EVT_SIGNAL_EXIT_BOOT_SERVICES</code> 事件。</li><li>OS Loader 为调用者，BDS 的责任止于成功启动 OS Loader。</li></ul><h3 id="_3-6-rt-阶段-runtime-phase" tabindex="-1">3.6 RT 阶段（Runtime Phase） <a class="header-anchor" href="#_3-6-rt-阶段-runtime-phase" aria-label="Permalink to &quot;3.6 RT 阶段（Runtime Phase）&quot;">​</a></h3><p>操作系统完全接管控制权后，固件进入 Runtime 阶段。</p><p><strong>保留服务</strong>：</p><ul><li><code>GetVariable()</code> / <code>SetVariable()</code> — 读写 NVRAM 变量。</li><li><code>GetTime()</code> / <code>SetTime()</code> — 硬件时钟操作。</li><li><code>ResetSystem()</code> — 系统重启 / 关机。</li><li><code>SetVirtualAddressMap()</code> — 虚拟地址映射（PAE 到虚拟地址转换）。</li><li><code>GetWakeupTime()</code> / <code>SetWakeupTime()</code> — 唤醒时间管理。</li></ul><p>Runtime Services 需要在操作系统进入虚拟内存模式后，通过 <code>SetVirtualAddressMap()</code> 更新内部地址映射，确保跨模式调用正确。</p><hr><h2 id="_4-核心架构概念" tabindex="-1">4. 核心架构概念 <a class="header-anchor" href="#_4-核心架构概念" aria-label="Permalink to &quot;4. 核心架构概念&quot;">​</a></h2><h3 id="_4-1-handle-protocol-模型" tabindex="-1">4.1 Handle / Protocol 模型 <a class="header-anchor" href="#_4-1-handle-protocol-模型" aria-label="Permalink to &quot;4.1 Handle / Protocol 模型&quot;">​</a></h3><p>UEFI 的核心抽象机制。Handle 是对象的标识，Protocol 是对象能力的描述。一个 Handle 上安装哪些 Protocol，表达该对象具备哪些能力。Protocol 通过 GUID 唯一标识，驱动间通过 LocateProtocol / InstallProtocolInterface 进行通信。</p><h3 id="_4-2-driver-binding-机制" tabindex="-1">4.2 Driver Binding 机制 <a class="header-anchor" href="#_4-2-driver-binding-机制" aria-label="Permalink to &quot;4.2 Driver Binding 机制&quot;">​</a></h3><p><code>EFI_DRIVER_BINDING_PROTOCOL</code> 定义了设备与驱动的匹配流程：</p><ul><li><strong>Supported()</strong>：测试驱动是否支持指定控制器。</li><li><strong>Start()</strong>：初始化控制器，安装新的 Protocol。</li><li><strong>Stop()</strong>：停止管理控制器，卸载 Protocol。</li></ul><p><code>ConnectController()</code> 遍历所有已注册的 Driver Binding，触发 Supported → Start 匹配流程，形成级联连接。</p><h3 id="_4-3-secure-boot" tabindex="-1">4.3 Secure Boot <a class="header-anchor" href="#_4-3-secure-boot" aria-label="Permalink to &quot;4.3 Secure Boot&quot;">​</a></h3><p>安全启动机制集成在 <code>LoadImage()</code> 流程中。启用时，固件根据以下密钥数据库验证镜像签名：</p><ul><li><strong>PK</strong>（Platform Key）：平台根密钥。</li><li><strong>KEK</strong>（Key Exchange Key）：用于更新 db / dbx。</li><li><strong>db</strong>：信任签名列表。</li><li><strong>dbx</strong>：吊销列表。</li></ul><p>验证失败则 <code>LoadImage()</code> 返回 <code>EFI_SECURITY_VIOLATION</code>，该启动项被跳过。</p><h3 id="_4-4-option-rom" tabindex="-1">4.4 Option ROM <a class="header-anchor" href="#_4-4-option-rom" aria-label="Permalink to &quot;4.4 Option ROM&quot;">​</a></h3><p>PCIe 设备板卡上的 Flash 芯片，包含设备固件。BDS 在 PCI 枚举阶段通过读取 Expansion ROM BAR 发现并加载。UEFI Image 形式的 Option ROM 可提供 Driver Binding 和 HII 配置界面。常见于 RAID 卡、NIC 网卡等外设。</p><hr><h2 id="_5-附录-参考规范" tabindex="-1">5. 附录：参考规范 <a class="header-anchor" href="#_5-附录-参考规范" aria-label="Permalink to &quot;5. 附录：参考规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td>UEFI Specification 2.10</td><td>UEFI 接口与服务规范</td></tr><tr><td>UEFI PI Specification 1.9</td><td>平台初始化架构规范（SEC / PEI / DXE 核心接口）</td></tr><tr><td>EDK II 源码</td><td>开源 UEFI 实现参考</td></tr></tbody></table>`,67)])])}const P=t(i,[["render",n]]);export{u as __pageData,P as default};
